INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Abklären technischer Aspekte Teil der Initiierung?', 2, '[{"text": "Ja", "correct": true, "because": "Technische Machbarkeit wird geprüft"}, {"text": "Nein", "correct": false, "because": "Es gehört zur Initiierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat das Abklären technischer Aspekte?', 3, '[{"text": "Machbarkeit des Projekts prüfen", "correct": true, "because": "Technische Basis klären"}, {"text": "Teamgröße festlegen", "correct": false, "because": "Anderer Fokus"}, {"text": "Kosten sofort senken", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Technische Aspekte beeinflussen die Projektplanung. b) Sie werden erst in der Durchführung geklärt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Initiierung ist entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden bei der technischen Abklärung untersucht?', 4, '[{"text": "Verfügbare Technologien", "correct": true, "because": "Bestimmen Machbarkeit"}, {"text": "Teamdynamik", "correct": false, "because": "Kein technischer Faktor"}, {"text": "Systemanforderungen", "correct": true, "because": "Definieren Voraussetzungen"}, {"text": "Technisches Know-how", "correct": true, "because": "Beeinflusst Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne technische Abklärung starten?', 2, '[{"text": "Nein", "correct": true, "because": "Technische Risiken bleiben unklar"}, {"text": "Ja", "correct": false, "because": "Fehlende Basis droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft beim Abklären technischer Aspekte?', 3, '[{"text": "Machbarkeitsstudie", "correct": true, "because": "Prüft technische Umsetzung"}, {"text": "Keine Analyse", "correct": false, "because": "Fehlt Grundlage"}, {"text": "Zufällige Annahmen", "correct": false, "because": "Ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die technische Abklärung nur für IT-Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor gehört zur technischen Abklärung?', 3, '[{"text": "Hardwareverfügbarkeit", "correct": true, "because": "Beeinflusst Umsetzung"}, {"text": "Kostenübersicht", "correct": false, "because": "Wirtschaftlicher Aspekt"}, {"text": "Teamzufriedenheit", "correct": false, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Technische Aspekte prüfen die Umsetzbarkeit. b) Sie sind für kleine Projekte unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, immer relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Abklärung technischer Aspekte?', 3, '[{"text": "Technische Probleme verzögern", "correct": true, "because": "Risiken unklar"}, {"text": "Projekt wird einfacher", "correct": false, "because": "Eher komplizierter"}, {"text": "Kosten sinken", "correct": false, "because": "Können steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können technische Aspekte in der Initiierung ignoriert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Entscheidend für Erfolg"}, {"text": "Ja", "correct": false, "because": "Risiko von Fehlern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine technische Abklärung?', 3, '[{"text": "Prüfung der Serverkapazität", "correct": true, "because": "Technische Basis"}, {"text": "Team soll motiviert sein", "correct": false, "because": "Kein technischer Fokus"}, {"text": "Kosten sollen niedrig sein", "correct": false, "because": "Wirtschaftlicher Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die technische Abklärung nur für Entwickler wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Beteiligten brauchen Klarheit"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur technischen Abklärung?', 4, '[{"text": "Softwareanforderungen", "correct": true, "because": "Definieren Technik"}, {"text": "Unklare Annahmen", "correct": false, "because": "Fehlt Präzision"}, {"text": "Verfügbare Ressourcen", "correct": true, "because": "Beeinflussen Machbarkeit"}, {"text": "Technische Risiken", "correct": true, "because": "Müssen bewertet werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die technische Abklärung dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die technische Abklärung?', 3, '[{"text": "Sichert technische Basis", "correct": true, "because": "Vermeidet Probleme"}, {"text": "Reduziert Teamgröße", "correct": false, "because": "Anderer Fokus"}, {"text": "Ignoriert Kosten", "correct": false, "because": "Kann Kosten beeinflussen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die technische Abklärung ohne Experten erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Fachwissen oft nötig"}, {"text": "Ja", "correct": false, "because": "Experten verbessern Analyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die technische Abklärung?', 3, '[{"text": "Fehlendes Fachwissen", "correct": true, "because": "Verhindert Klarheit"}, {"text": "Klares Ziel", "correct": false, "because": "Fördert Abklärung"}, {"text": "Gute Dokumentation", "correct": false, "because": "Unterstützt Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Technische Abklärung prüft Ressourcen. b) Sie definiert das Budget.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist wirtschaftlicher Aspekt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Ziel der technischen Abklärung?', 3, '[{"text": "Technische Umsetzbarkeit sichern", "correct": true, "because": "Grundlage schaffen"}, {"text": "Zeit verlängern", "correct": false, "because": "Kein Ziel"}, {"text": "Team motivieren", "correct": false, "because": "Anderer Fokus"}]');
